package io.github.marcomow.yuvomi.core.design

import android.content.res.AssetManager
import androidx.compose.ui.graphics.Color
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive

/**
 * Upstream's colour tokens (`assets/tokens.json`, generated by upstream/sync.sh
 * from `public/styles/tokens.css`). ADR 0002.
 */
class Tokens(private val light: Map<String, Color>, private val dark: Map<String, Color>) {

    fun color(name: String, isDark: Boolean): Color =
        (if (isDark) dark[name] else light[name]) ?: light[name] ?: FALLBACK

    companion object {
        private val FALLBACK = Color(0xFF6C3AED)

        fun load(assets: AssetManager): Tokens = runCatching {
            parse(assets.open("tokens.json").bufferedReader().use { it.readText() })
        }.getOrElse { Tokens(emptyMap(), emptyMap()) }

        fun parse(text: String): Tokens {
            val root = Json.parseToJsonElement(text) as JsonObject
            fun side(name: String): Map<String, Color> = (root[name] as? JsonObject).orEmpty().mapNotNull { (k, v) ->
                parseColor((v as? JsonPrimitive)?.content)?.let { k to it }
            }.toMap()
            return Tokens(side("light"), side("dark"))
        }

        /** `#RGB`, `#RRGGBB`, `#RRGGBBAA`, `rgb(r, g, b)`, `rgba(r, g, b, a)`. */
        fun parseColor(value: String?): Color? {
            val v = value?.trim() ?: return null
            if (v.startsWith("#")) {
                val hex = v.drop(1)
                val full = when (hex.length) {
                    3 -> hex.map { "$it$it" }.joinToString("") + "FF"
                    6 -> hex + "FF"
                    8 -> hex
                    else -> return null
                }
                val n = full.toLongOrNull(16) ?: return null
                val r = (n shr 24) and 0xFF
                val g = (n shr 16) and 0xFF
                val b = (n shr 8) and 0xFF
                val a = n and 0xFF
                return Color(r.toInt(), g.toInt(), b.toInt(), a.toInt())
            }
            val m = Regex("""rgba?\(([^)]*)\)""").matchEntire(v) ?: return null
            val parts = m.groupValues[1].split(',').map { it.trim() }
            if (parts.size < 3) return null
            val rgb = parts.take(3).map { it.toFloatOrNull() ?: return null }
            val alpha = parts.getOrNull(3)?.toFloatOrNull() ?: 1f
            return Color(rgb[0] / 255f, rgb[1] / 255f, rgb[2] / 255f, alpha)
        }
    }
}
